(function () {
  "use strict";
  // Layer JS loads on every page: it does nothing without a workbench.
  var workbench = document.querySelector("[data-studio-workbench]");
  if (!workbench) {
    return;
  }
  // studio.js (studio:studio, order 0) runs first and gives the API.
  var S = window.ScrudStudio;
  if (!S) return;

  // The strip's promote panels, one per `actions.promote` entry
  // (studio:status renders them): "Promote to <target>…" opens its panel
  // and loads the push preview into it (never embedded at render), in the
  // scope studio studio-push. Apply and Propose are the strip's own
  // fixed-body buttons, sent by htmx; this script only turns Apply on once
  // the review shows no conflict, readable or not (a push with any conflict
  // is refused). "Preview after push" shows the target with T pushed.
  var REVIEW_SCOPE = "studio studio-push";
  var LOADING = "Apply waits for the review to load.";
  var UNLOADED = "Apply is off: the review could not be loaded.";

  function plural(count, word) {
    return count + " " + word + (count === 1 ? "" : "s");
  }

  function part(box, selector) {
    return box.querySelector(selector);
  }

  // Show `text` (as text) in the panel's `selector`, or hide it when empty.
  function say(box, selector, text) {
    var node = part(box, selector);
    if (!node) return;
    node.textContent = text || "";
    if (text) node.removeAttribute("hidden");
    else node.setAttribute("hidden", "");
  }

  // Apply on or off, with the reason it is off.
  function setApply(box, on, reason) {
    var apply = part(box, ".studio-apply");
    if (!apply) {
      say(box, "[data-studio-promote-reason]", "");
      return;
    }
    if (on) apply.removeAttribute("disabled");
    else apply.setAttribute("disabled", "");
    say(box, "[data-studio-promote-reason]", on ? "" : reason);
  }

  // Load the push of T into the panel's target: the push preview, an htmx
  // GET in the review's scope (scrud-ui.js adds the branch and safe mode).
  function load(box) {
    var review = part(box, "[data-studio-promote-review]");
    var htmx = window.htmx;
    if (!review || !htmx || typeof htmx.ajax !== "function") return;
    var src = box.getAttribute("data-studio-promote-src") || "";
    var target = box.getAttribute("data-studio-promote") || "";
    while (review.firstChild) review.removeChild(review.firstChild);
    setApply(box, false, LOADING);
    say(box, "[data-studio-promote-note]", "");
    htmx.ajax(
      "GET",
      src + (src.indexOf("?") < 0 ? "?" : "&") + "target=" + encodeURIComponent(target),
      {
        source: review,
        target: review,
        swap: "innerHTML",
        headers: { "Scrud-UI-Scope": REVIEW_SCOPE }
      }
    );
  }

  // A count the review exposes: a non-negative integer, else null.
  function count(found, name) {
    var text = found.getAttribute(name);
    return /^[0-9]+$/.test(String(text)) ? Number(text) : null;
  }

  // The review's answer: Apply goes on only for a loaded review with no
  // conflict.
  function reviewed(box, review, detail) {
    var found = detail.successful ? review.querySelector("[data-studio-push-preview]") : null;
    if (!found) {
      var why = detail.successful ? "" : " " + S.errorText(detail.xhr);
      setApply(box, false, UNLOADED + why);
      return;
    }
    var readable = count(found, "data-studio-conflicts");
    var hidden = count(found, "data-studio-unreadable-conflicts");
    if (readable === null || hidden === null) {
      setApply(box, false, UNLOADED);
      return;
    }
    var total = readable + hidden;
    if (!total) {
      setApply(box, true, "");
      return;
    }
    var what = plural(total, "conflict");
    if (hidden === total) what += " on items you can't read";
    else if (hidden) what += " (" + hidden + " on items you can't read)";
    setApply(
      box,
      false,
      "Apply is off: this push has " +
        what +
        ", and a push with any conflict is refused. Pull, resolve them, and push again."
    );
  }

  function toggle(box, opener) {
    var panel = part(box, "[data-studio-promote-panel]");
    if (!panel) return;
    var open = panel.hasAttribute("hidden");
    if (open) panel.removeAttribute("hidden");
    else panel.setAttribute("hidden", "");
    opener.setAttribute("aria-expanded", open ? "true" : "false");
    if (open) load(box);
  }

  // The preview of the target with T's overrides layered on, as the push
  // would write them (never with drafts).
  function previewAfterPush(box) {
    var target = box.getAttribute("data-studio-promote") || "";
    var sent = S.submitPreview({ after_push: { source: S.branch }, branch: target });
    say(
      box,
      "[data-studio-promote-note]",
      sent
        ? "The preview shows " + target + " after this push."
        : "Choose a type to preview " + target + " after this push."
    );
  }

  workbench.addEventListener("click", function (evt) {
    var target = evt.target;
    if (!target || typeof target.closest !== "function") return;
    var box = target.closest("[data-studio-promote]");
    if (!box) return;
    var opener = target.closest("[data-studio-promote-open]");
    if (opener) {
      toggle(box, opener);
      return;
    }
    if (target.closest("[data-studio-after-push]")) previewAfterPush(box);
  });

  document.addEventListener("htmx:afterRequest", function (evt) {
    var review = evt.target;
    if (!review || typeof review.hasAttribute !== "function") return;
    if (!review.hasAttribute("data-studio-promote-review")) return;
    if (!workbench.contains(review)) return;
    var box = review.closest("[data-studio-promote]");
    if (box) reviewed(box, review, evt.detail || {});
  });
})();
